(() => {
 const {scenarios,outcome}=ExecutiveSimulation;
 const labels=['Business momentum','Stakeholder trust','Operational resilience'];
 let selected=null,choices=[],revealed=false,pending=null,reflection='';
 let coachText='',coachError='',coaching=false,coachRequest=0;
 const host=document.getElementById('simulator');
 const button=(label,action,kind='secondary')=>`<button class="${kind}" data-sim="${action}">${label}</button>`;
 const escape=value=>value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function metrics(){return `<div class="sim-metrics">${outcome(choices,selected).map((value,i)=>`<div class="stat"><div class="stat-label">${labels[i]}</div><div class="stat-value">${value}<small> / 100</small></div><div class="progress-track" role="meter" aria-label="${labels[i]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><div style="width:${value}%"></div></div></div>`).join('')}</div>`;}
 function render(){
  if(!selected){host.innerHTML=`<div class="sim-intro"><div><div class="eyebrow">THE EXECUTIVE PRACTICE ROOM</div><h2>Make the call.<br>Discover the trade-offs.</h2><p>Step into the moments that test executive judgment. Balance competing priorities, experience the consequences, and take a new perspective into your next decision.</p><div class="hero-meta"><span>◷ 6 minutes per scenario</span><span>◇ 3 decisions</span><span>♧ Private session</span></div></div><span class="sim-symbol" aria-hidden="true">⎇</span></div><div class="sim-how"><div><span>01</span><b>Read the room</b><p>Understand the stakes and the people involved.</p></div><div><span>02</span><b>Make your decisions</b><p>Choose an action and explore its consequences.</p></div><div><span>03</span><b>Reflect and apply</b><p>Review your approach and capture a next step.</p></div></div><div class="section-heading"><h2>Choose your challenge</h2><span class="subtle-tag">No single perfect answer</span></div><div class="sim-cards">${scenarios.map((s,i)=>`<article class="report-panel"><div class="sim-card-top"><span class="dimension-icon" aria-hidden="true">${['◎','◇','↗'][i%3]}</span><span class="eyebrow">SCENARIO ${String(i+1).padStart(2,'0')}</span></div><div class="eyebrow">${s.category}</div><h2>${s.name}</h2><p>${s.summary}</p><div class="sim-card-meta">◷ ${s.time} · 3 decisions</div>${button('Enter scenario ↗',s.id,'primary')}</article>`).join('')}</div><p class="panel-intro sim-disclosure">AI Executive Decision Simulator · Guided practice with authored scenarios and illustrative consequences. Optional live AI coaching is available in your debrief when configured. Decisions and notes stay in this session unless you request coaching, which sends your scenario, choices, and reflection to OpenAI. Avoid confidential information.</p>`;return;}
  if(choices.length===selected.rounds.length&&!revealed){host.innerHTML=`<div class="report-panel"><div class="eyebrow">SIMULATION COMPLETE · YOUR DEBRIEF</div><h2>${selected.name}</h2><p class="panel-intro">Every choice moves more than one priority. Review how your approach balanced progress, relationships, and sustainable execution.</p>${metrics()}<p class="panel-intro">Illustrative indicators start at 50 and reflect authored trade-offs. They are not predictions or an assessment of your leadership ability.</p><h3>Your decision trail</h3>${choices.map((c,i)=>`<div class="sim-trail"><div class="eyebrow">DECISION 0${i+1}</div><p>${selected.rounds[i].prompt}</p><h3>${selected.rounds[i].options[c][0]}</h3><p>${selected.rounds[i].options[c][3]}</p></div>`).join('')}<div class="insight"><div class="eyebrow">TAKE IT INTO YOUR NEXT CONVERSATION</div><h3>What would you do differently with more information?</h3><p>Which stakeholder carried the cost of your choices? What evidence would you seek before acting in your organization?</p><label for="sim-reflection">Your reflection and next step</label><textarea id="sim-reflection" rows="4" maxlength="3000" placeholder="One assumption to question. One action to take…">${escape(reflection)}</textarea><small>Optional · Included in your downloaded debrief.</small></div>${coachPanel()}<div class="panel-actions"><button class="secondary" data-print="#simulator">Print / Save as PDF</button>${button('Download debrief ↓','download','primary')}${button('Try again','retry')}${button('Explore scenarios','home')}</div></div>`;return;}
  const index=revealed?choices.length-1:choices.length,round=selected.rounds[index];
  host.innerHTML=`<div class="sim-layout"><aside class="report-panel sim-brief"><div class="eyebrow">${selected.category}</div><h2>${selected.name}</h2><p>${selected.context}</p><div class="eyebrow">AT THE TABLE</div><p>${selected.stakeholders}</p><ol class="sim-steps" aria-label="Scenario progress">${selected.rounds.map((r,i)=>`<li ${i===index?'aria-current="step"':''}><span>${i<choices.length?'✓':`0${i+1}`}</span>Decision ${i+1}${i===index?' · Current':''}</li>`).join('')}</ol>${button('← All scenarios','home')}</aside><div class="question-panel"><div class="eyebrow">DECISION 0${index+1} / 03</div><div class="progress-track"><div style="width:${choices.length/3*100}%"></div></div>${index>0?`<p class="sim-previous"><b>Your previous decision:</b> ${selected.rounds[index-1].options[choices[index-1]][0]}</p>`:''}<h2>${round.prompt}</h2><div class="sim-options" role="group" aria-label="Choose your action">${round.options.map((o,i)=>`<button class="sim-option" data-choice="${i}" ${revealed?'disabled':''} aria-pressed="${(revealed?choices[index]:pending)===i}"><span class="sim-option-letter">${String.fromCharCode(65+i)}</span><span><b>${o[0]}</b><small>${o[1]}</small></span></button>`).join('')}</div>${revealed?`<div class="insight sim-consequence" role="status"><div class="eyebrow">THE CONSEQUENCE</div><p>${round.options[choices[index]][3]}</p></div><div class="panel-actions"><span class="panel-intro">Pause. What trade-off did you make?</span>${button(index===2?'View debrief →':'Next decision →','next','primary')}</div>`:`<div class="panel-actions"><p class="panel-intro">Select an action, then commit to see its consequence.</p><button class="primary" data-sim="commit" ${pending===null?'disabled':''}>Commit decision →</button></div>`}</div></div><div class="section-heading sim-impact-heading"><h2>Your priorities in balance</h2><span class="subtle-tag">${choices.length} of 3 decisions committed</span></div>${metrics()}<p class="panel-intro">Illustrative indicators · Each starts at 50. Every decision can affect more than one priority.</p>`;
 }
 function coachPanel(){return `<section class="sim-coach" aria-labelledby="sim-coach-heading" aria-busy="${coaching}"><div class="eyebrow">LIVE AI EXECUTIVE COACH</div><h3 id="sim-coach-heading">Turn your decisions into a next step</h3><p>Request a personalized perspective on your decision trail. This sends the scenario, your choices, and your current reflection to OpenAI. Avoid confidential or identifying details. AI guidance can be mistaken; use your judgment.</p><div role="status" aria-live="polite">${coaching?'<p>Preparing your coaching debrief…</p>':''}${coachError?`<p>${escape(coachError)}</p>`:''}</div>${coachText?`<p class="sim-coach-response">${escape(coachText)}</p><small>AI-generated coaching · Included in your downloaded debrief. Edit your reflection and request again for an updated perspective.</small>`:''}<button class="primary" data-sim="coach" ${coaching?'disabled':''}>${coaching?'Preparing coaching…':coachText?'Refresh coaching':coachError?'Retry AI coaching':'Request AI coaching'}</button></section>`;}
 function resetCoach(){coachRequest++;coaching=false;coachText='';coachError='';}
 async function requestCoach(){
  if(coaching||!selected||revealed||choices.length!==selected.rounds.length)return;
  const request=++coachRequest;
  coaching=true;coachError='';render();
  try{
   const response=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(35000),body:JSON.stringify({scenarioId:selected.id,choices:choices.slice(),reflection})});
   const data=await response.json();
   if(!response.ok)throw new Error(data.error||'Coaching is unavailable. Please try again.');
   if(typeof data.text!=='string'||!data.text.trim())throw new Error('The coach returned no feedback. Please try again.');
   if(request===coachRequest)coachText=data.text;
  }catch(error){if(request===coachRequest)coachError=error.name==='TimeoutError'?'Coaching timed out. Please try again.':error.message||'Coaching is unavailable. Please try again.';}
  finally{if(request===coachRequest){coaching=false;render();}}
 }
 host.addEventListener('input',e=>{if(e.target.id==='sim-reflection')reflection=e.target.value;});
 host.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.sim==='coach'){void requestCoach();return;}
  if(b.dataset.choice!==undefined&&!revealed){pending=Number(b.dataset.choice);host.querySelectorAll('[data-choice]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.choice)===pending));host.querySelector('[data-sim="commit"]').disabled=false;return;}
  if(b.dataset.sim==='commit'&&pending!==null&&!revealed){choices.push(pending);pending=null;revealed=true;}
  else if(b.dataset.sim==='next'){revealed=false;}
  else if(b.dataset.sim==='home'){selected=null;choices=[];pending=null;revealed=false;reflection='';resetCoach();}
  else if(b.dataset.sim==='retry'){choices=[];pending=null;revealed=false;reflection='';resetCoach();}
  else if(b.dataset.sim==='download'){
   const lines=['COUTURE LEADERSHIP — EXECUTIVE DECISION DEBRIEF',selected.name,'',...outcome(choices,selected).map((n,i)=>`${labels[i]}: ${n}/100`),'',...choices.flatMap((c,i)=>[`Decision ${i+1}: ${selected.rounds[i].prompt}`,selected.rounds[i].options[c][0],selected.rounds[i].options[c][3],'']),'My reflection and next step:',reflection||'No reflection added.','','AI EXECUTIVE COACH (AI-generated):',coachText||'No AI coaching requested.','','Authored practice scenario. Illustrative indicators, not predictions or an assessment of leadership ability.'];
   const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`couture-${selected.id}-debrief.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;
  }
  else if(scenarios.some(s=>s.id===b.dataset.sim)){selected=scenarios.find(s=>s.id===b.dataset.sim);choices=[];pending=null;revealed=false;reflection='';resetCoach();}
  else return;
  render();const heading=host.querySelector(revealed?'.sim-consequence':'.question-panel h2')||host.querySelector('h2');heading?.setAttribute('tabindex','-1');heading?.focus();
 });
 render();
})();
